//! Four-valued logic vectors (0, 1, x, z): a port of `@twint/4vl`.
//!
//! Same encoding as 4vl: two bit planes A and B, and per bit
//! (A, B) = (0, 0) is 0, (0, 1) is x, (1, 1) is 1 and (1, 0) is z.
//! Words are 64 bits instead of 32, and values are always normalized (plane
//! bits at or above `bits` are 0), so the derived `Eq`/`Hash` compare values.
//!
//! The port is faithful, quirks included: `tests/4vl.rs` replays cases
//! generated by 4vl itself (`tests/gen_4vl_fixtures.mjs`).

use smallvec::SmallVec;

mod mem;
pub use mem::{LogicMem, MemItem};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Bit {
    Zero,
    One,
    X,
    Z,
}

impl Bit {
    fn from_ab(a: u64, b: u64) -> Bit {
        match (a & 1, b & 1) {
            (0, 0) => Bit::Zero,
            (0, _) => Bit::X,
            (_, 0) => Bit::Z,
            _ => Bit::One,
        }
    }

    /// Plane words for a run of this bit.
    fn planes(self) -> (u64, u64) {
        match self {
            Bit::Zero => (0, 0),
            Bit::X => (0, !0),
            Bit::One => (!0, !0),
            Bit::Z => (!0, 0),
        }
    }

    pub fn to_char(self) -> char {
        match self {
            Bit::Zero => '0',
            Bit::One => '1',
            Bit::X => 'x',
            Bit::Z => 'z',
        }
    }
}

/// Plane A words, then plane B words.
type Words = SmallVec<[u64; 2]>;

#[derive(Clone, PartialEq, Eq, Hash)]
pub struct LogicVec {
    bits: usize,
    w: Words,
}

impl std::fmt::Debug for LogicVec {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "LogicVec({}'b{})", self.bits, self.to_bin())
    }
}

fn nwords(bits: usize) -> usize {
    bits.div_ceil(64)
}

fn last_mask(bits: usize) -> u64 {
    match bits % 64 {
        0 => !0,
        r => (1 << r) - 1,
    }
}

/// `len` (<= 64) bits of plane `p` from bit `pos`; bits past the end read as 0.
fn field(p: &[u64], pos: usize, len: usize) -> u64 {
    let (k, sh) = (pos / 64, pos % 64);
    let mut v = p.get(k).copied().unwrap_or(0) >> sh;
    if sh != 0 {
        v |= p.get(k + 1).copied().unwrap_or(0) << (64 - sh);
    }
    if len < 64 { v & ((1 << len) - 1) } else { v }
}

/// Sets bits `from..to` of plane `p` to 1.
fn fill_ones(p: &mut [u64], from: usize, to: usize) {
    for i in from..to {
        p[i / 64] |= 1 << (i % 64);
    }
}

/// z behaves as x for every bitwise and reduction operator (IEEE 1800-2023
/// tables 11-11 to 11-18), so operands are normalized with this first.
fn z2x(a: u64, b: u64) -> (u64, u64) {
    (a & b, a | b)
}

impl LogicVec {
    fn from_words(bits: usize, w: Words) -> LogicVec {
        debug_assert_eq!(w.len(), 2 * nwords(bits));
        let mut v = LogicVec { bits, w };
        let n = nwords(bits);
        if n > 0 {
            let m = last_mask(bits);
            v.w[n - 1] &= m;
            v.w[2 * n - 1] &= m;
        }
        v
    }

    fn zeroed(bits: usize) -> Words {
        SmallVec::from_elem(0, 2 * nwords(bits))
    }

    fn a(&self) -> &[u64] {
        &self.w[..nwords(self.bits)]
    }

    fn b(&self) -> &[u64] {
        &self.w[nwords(self.bits)..]
    }

    /// (a, b, mask of the bits in use) per word.
    fn masked_words(&self) -> impl Iterator<Item = (u64, u64, u64)> + '_ {
        let n = nwords(self.bits);
        (0..n).map(move |i| {
            let m = if i == n - 1 { last_mask(self.bits) } else { !0 };
            (self.w[i], self.w[n + i], m)
        })
    }

    pub fn make(bits: usize, init: Bit) -> LogicVec {
        let n = nwords(bits);
        let (a, b) = init.planes();
        let mut w = Words::with_capacity(2 * n);
        w.extend(std::iter::repeat_n(a, n));
        w.extend(std::iter::repeat_n(b, n));
        Self::from_words(bits, w)
    }

    pub fn zeros(bits: usize) -> LogicVec {
        Self::make(bits, Bit::Zero)
    }

    pub fn ones(bits: usize) -> LogicVec {
        Self::make(bits, Bit::One)
    }

    pub fn xes(bits: usize) -> LogicVec {
        Self::make(bits, Bit::X)
    }

    pub fn zes(bits: usize) -> LogicVec {
        Self::make(bits, Bit::Z)
    }

    pub fn from_bool(b: bool, bits: usize) -> LogicVec {
        Self::make(bits, if b { Bit::One } else { Bit::Zero })
    }

    /// Least significant bit first (4vl's `fromArray`).
    pub fn from_bits(bits: &[Bit]) -> LogicVec {
        let n = nwords(bits.len());
        let mut w = Self::zeroed(bits.len());
        for (i, bit) in bits.iter().enumerate() {
            let (a, b) = bit.planes();
            w[i / 64] |= (a & 1) << (i % 64);
            w[n + i / 64] |= (b & 1) << (i % 64);
        }
        Self::from_words(bits.len(), w)
    }

    /// Concatenation, least significant vector first.
    pub fn concat(vs: &[&LogicVec]) -> LogicVec {
        let bits = vs.iter().map(|v| v.bits).sum();
        let n = nwords(bits);
        let mut w = Self::zeroed(bits);
        let mut off = 0;
        for v in vs {
            let (base, sh) = (off / 64, off % 64);
            for (i, (a, b)) in v.a().iter().zip(v.b()).enumerate() {
                w[base + i] |= a << sh;
                w[n + base + i] |= b << sh;
                if sh != 0 && base + i + 1 < n {
                    w[base + i + 1] |= a >> (64 - sh);
                    w[n + base + i + 1] |= b >> (64 - sh);
                }
            }
            off += v.bits;
        }
        Self::from_words(bits, w)
    }

    /// Parses digits of `per_char` bits each, most significant first. Without
    /// `nbits` the width is the digits' width. A longer string is truncated; a
    /// shorter one is extended with x or z if its top bit is x or z, else with 0.
    fn parse_digits(
        s: &str,
        per_char: usize,
        nbits: Option<usize>,
        digit: impl Fn(u8) -> Option<(u64, u64)>,
    ) -> Option<LogicVec> {
        let m = s.len() * per_char;
        let bits = nbits.unwrap_or(m);
        let n = nwords(bits);
        let mut w = Self::zeroed(bits);
        for (i, c) in s.bytes().rev().enumerate() {
            let (da, db) = digit(c)?;
            let (k, sh) = (i * per_char / 64, i * per_char % 64);
            if k < n {
                w[k] |= da << sh;
                w[n + k] |= db << sh;
            }
            if sh + per_char > 64 && k + 1 < n {
                w[k + 1] |= da >> (64 - sh);
                w[n + k + 1] |= db >> (64 - sh);
            }
        }
        if m > 0 && m < bits {
            let top = s.as_bytes()[0];
            let (ta, tb) = digit(top)?;
            let top_bit = (per_char - 1) as u32;
            match ((ta >> top_bit) & 1, (tb >> top_bit) & 1) {
                (0, 1) => fill_ones(&mut w[n..], m, bits),
                (1, 0) => fill_ones(&mut w[..n], m, bits),
                _ => {}
            }
        }
        Some(Self::from_words(bits, w))
    }

    /// Characters `0`, `1`, `x`, `z`, most significant first.
    pub fn from_bin(s: &str, nbits: Option<usize>) -> Option<LogicVec> {
        Self::parse_digits(s, 1, nbits, |c| match c {
            b'0' => Some((0, 0)),
            b'1' => Some((1, 1)),
            b'x' => Some((0, 1)),
            b'z' => Some((1, 0)),
            _ => None,
        })
    }

    /// Characters `0`-`7`, `x`, `z` (3 bits each).
    pub fn from_oct(s: &str, nbits: Option<usize>) -> Option<LogicVec> {
        Self::parse_digits(s, 3, nbits, |c| match c {
            b'0'..=b'7' => Some(((c - b'0') as u64, (c - b'0') as u64)),
            b'x' => Some((0, 7)),
            b'z' => Some((7, 0)),
            _ => None,
        })
    }

    /// Characters `0`-`9`, `a`-`f`, `x`, `z` (4 bits each). Lowercase only, like 4vl.
    pub fn from_hex(s: &str, nbits: Option<usize>) -> Option<LogicVec> {
        Self::parse_digits(s, 4, nbits, |c| match c {
            b'0'..=b'9' => Some(((c - b'0') as u64, (c - b'0') as u64)),
            b'a'..=b'f' => Some(((c - b'a' + 10) as u64, (c - b'a' + 10) as u64)),
            b'x' => Some((0, 0xf)),
            b'z' => Some((0xf, 0)),
            _ => None,
        })
    }

    /// A number given as magnitude words and sign, in two's complement. Without
    /// `nbits`: just enough bits for a non-negative value (at least 1), and
    /// one more than the magnitude's for a negative one (4vl's `fromNumber`).
    fn from_magnitude(neg: bool, mag: &[u64], nbits: Option<usize>) -> LogicVec {
        let mag_bits = mag
            .iter()
            .rposition(|&x| x != 0)
            .map_or(0, |k| 64 * k + 64 - mag[k].leading_zeros() as usize);
        let neg = neg && mag_bits > 0;
        let bits = nbits.unwrap_or(if neg { mag_bits + 1 } else { mag_bits.max(1) });
        let n = nwords(bits);
        let mut w = Self::zeroed(bits);
        for (i, x) in mag.iter().take(n).enumerate() {
            w[i] = *x;
        }
        if neg {
            let mut carry = true;
            for x in &mut w[..n] {
                let (v, c) = (!*x).overflowing_add(carry as u64);
                *x = v;
                carry = c;
            }
        }
        let (a, b) = w.split_at_mut(n);
        b.copy_from_slice(a);
        Self::from_words(bits, w)
    }

    pub fn from_u64(v: u64, nbits: Option<usize>) -> LogicVec {
        Self::from_magnitude(false, &[v], nbits)
    }

    pub fn from_i64(v: i64, nbits: Option<usize>) -> LogicVec {
        Self::from_magnitude(v < 0, &[v.unsigned_abs()], nbits)
    }

    /// Decimal digits with an optional leading `-`, of any size; no digits is 0.
    pub fn from_dec(s: &str, nbits: Option<usize>) -> Option<LogicVec> {
        let (neg, digits) = match s.strip_prefix('-') {
            Some("") => return None,
            Some(d) => (true, d),
            None => (false, s),
        };
        let mut mag: Vec<u64> = vec![0];
        for c in digits.bytes() {
            if !c.is_ascii_digit() {
                return None;
            }
            let mut carry = (c - b'0') as u128;
            for x in &mut mag {
                let v = *x as u128 * 10 + carry;
                *x = v as u64;
                carry = v >> 64;
            }
            if carry != 0 {
                mag.push(carry as u64);
            }
        }
        Some(Self::from_magnitude(neg, &mag, nbits))
    }

    /// Verilog-like literal: optional width, optional `'`, then `b`, `o`, `h`
    /// or `d` and digits, e.g. `8'hff`, `b101`, `4'd9` (4vl's `fromString`).
    pub fn parse(s: &str) -> Option<LogicVec> {
        let split = s.bytes().position(|c| !c.is_ascii_digit()).unwrap_or(s.len());
        let (width, rest) = s.split_at(split);
        let nbits = if width.is_empty() { None } else { Some(width.parse().ok()?) };
        let rest = rest.strip_prefix('\'').unwrap_or(rest);
        let (base, num) = rest.split_at_checked(1)?;
        match base {
            "b" => Self::from_bin(num, nbits),
            "o" => Self::from_oct(num, nbits),
            "h" => Self::from_hex(num, nbits),
            "d" if !num.starts_with('-') => Self::from_dec(num, nbits),
            _ => None,
        }
    }

    pub fn bits(&self) -> usize {
        self.bits
    }

    /// Bit `n`; past the end it reads as 0, like in 4vl.
    pub fn get(&self, n: usize) -> Bit {
        if n >= self.bits {
            return Bit::Zero;
        }
        Bit::from_ab(self.a()[n / 64] >> (n % 64), self.b()[n / 64] >> (n % 64))
    }

    /// The most significant bit (0 for an empty vector).
    pub fn msb(&self) -> Bit {
        self.bits.checked_sub(1).map_or(Bit::Zero, |n| self.get(n))
    }

    pub fn lsb(&self) -> Bit {
        self.get(0)
    }

    /// All ones (true for an empty vector).
    pub fn is_high(&self) -> bool {
        self.masked_words().all(|(a, b, m)| a == m && b == m)
    }

    /// All zeros (true for an empty vector).
    pub fn is_low(&self) -> bool {
        self.masked_words().all(|(a, b, _)| a == 0 && b == 0)
    }

    /// All z (true for an empty vector).
    pub fn is_z(&self) -> bool {
        self.masked_words().all(|(a, b, m)| a == m && b == 0)
    }

    /// At least one bit is 0 or 1 (false for an empty vector).
    pub fn is_defined(&self) -> bool {
        self.masked_words().any(|(a, b, m)| !(a ^ b) & m != 0)
    }

    /// No bit is x or z (true for an empty vector).
    pub fn is_fully_defined(&self) -> bool {
        self.masked_words().all(|(a, b, _)| a ^ b == 0)
    }

    fn bitwise(&self, o: &LogicVec, op: &str, f: impl Fn(u64, u64, u64, u64) -> (u64, u64)) -> LogicVec {
        assert_eq!(self.bits, o.bits, "LogicVec::{op}() called with vectors of different sizes");
        let n = nwords(self.bits);
        let mut w = Self::zeroed(self.bits);
        for i in 0..n {
            let (a1, b1) = z2x(self.w[i], self.w[n + i]);
            let (a2, b2) = z2x(o.w[i], o.w[n + i]);
            (w[i], w[n + i]) = f(a1, b1, a2, b2);
        }
        Self::from_words(self.bits, w)
    }

    pub fn and(&self, o: &LogicVec) -> LogicVec {
        self.bitwise(o, "and", |a1, b1, a2, b2| (a1 & a2, b1 & b2))
    }

    pub fn or(&self, o: &LogicVec) -> LogicVec {
        self.bitwise(o, "or", |a1, b1, a2, b2| (a1 | a2, b1 | b2))
    }

    pub fn xor(&self, o: &LogicVec) -> LogicVec {
        self.bitwise(o, "xor", |a1, b1, a2, b2| ((a1 | a2) & (b1 ^ b2), (a1 & a2) ^ (b1 | b2)))
    }

    pub fn nand(&self, o: &LogicVec) -> LogicVec {
        self.bitwise(o, "nand", |a1, b1, a2, b2| (!(b1 & b2), !(a1 & a2)))
    }

    pub fn nor(&self, o: &LogicVec) -> LogicVec {
        self.bitwise(o, "nor", |a1, b1, a2, b2| (!(b1 | b2), !(a1 | a2)))
    }

    pub fn xnor(&self, o: &LogicVec) -> LogicVec {
        self.bitwise(o, "xnor", |a1, b1, a2, b2| (!((a1 & a2) ^ (b1 | b2)), !((a1 | a2) & (b1 ^ b2))))
    }

    pub fn not(&self) -> LogicVec {
        let n = nwords(self.bits);
        let mut w = Self::zeroed(self.bits);
        for i in 0..n {
            let (a, b) = z2x(self.w[i], self.w[n + i]);
            (w[i], w[n + i]) = (!b, !a);
        }
        Self::from_words(self.bits, w)
    }

    /// 1 where the bit is x or z, 0 elsewhere.
    pub fn xmask(&self) -> LogicVec {
        let n = nwords(self.bits);
        let mut w = Self::zeroed(self.bits);
        for i in 0..n {
            let v = self.w[i] ^ self.w[n + i];
            (w[i], w[n + i]) = (v, v);
        }
        Self::from_words(self.bits, w)
    }

    /// (all ones, any one) of each z2x-normalized plane: (A, B).
    fn fold_planes(&self) -> ((bool, bool), (bool, bool)) {
        let (mut all_a, mut any_a, mut all_b, mut any_b) = (true, false, true, false);
        for (a, b, m) in self.masked_words() {
            let (a, b) = z2x(a, b);
            all_a &= a == m;
            all_b &= b == m;
            any_a |= a != 0;
            any_b |= b != 0;
        }
        ((all_a, any_a), (all_b, any_b))
    }

    fn bit1(a: bool, b: bool) -> LogicVec {
        Self::make(1, Bit::from_ab(a as u64, b as u64))
    }

    pub fn reduce_and(&self) -> LogicVec {
        let ((all_a, _), (all_b, _)) = self.fold_planes();
        Self::bit1(all_a, all_b)
    }

    pub fn reduce_or(&self) -> LogicVec {
        let ((_, any_a), (_, any_b)) = self.fold_planes();
        Self::bit1(any_a, any_b)
    }

    pub fn reduce_nand(&self) -> LogicVec {
        let ((all_a, _), (all_b, _)) = self.fold_planes();
        Self::bit1(!all_b, !all_a)
    }

    pub fn reduce_nor(&self) -> LogicVec {
        let ((_, any_a), (_, any_b)) = self.fold_planes();
        Self::bit1(!any_b, !any_a)
    }

    pub fn reduce_xor(&self) -> LogicVec {
        let (mut has_x, mut parity) = (false, 0);
        for (a, b, _) in self.masked_words() {
            let (a, b) = z2x(a, b);
            has_x |= !a & b != 0;
            parity ^= a.count_ones() & 1;
        }
        let v = parity == 1;
        Self::bit1(v && !has_x, v || has_x)
    }

    pub fn reduce_xnor(&self) -> LogicVec {
        self.reduce_xor().not()
    }

    /// Bits `start..end`, clamped like 4vl's `slice` (an empty vector if `start > end`).
    pub fn slice(&self, start: usize, end: usize) -> LogicVec {
        let end = end.min(self.bits).max(start);
        let bits = end - start;
        let n = nwords(bits);
        let mut w = Self::zeroed(bits);
        for j in 0..n {
            w[j] = field(self.a(), start + 64 * j, 64);
            w[n + j] = field(self.b(), start + 64 * j, 64);
        }
        Self::from_words(bits, w)
    }

    /// Least significant bit first (4vl's `toArray`).
    pub fn to_bits(&self) -> Vec<Bit> {
        (0..self.bits).map(|i| self.get(i)).collect()
    }

    pub fn to_bin(&self) -> String {
        (0..self.bits).rev().map(|i| self.get(i).to_char()).collect()
    }

    /// Digits of `g` bits, most significant first: the digit if all its bits
    /// are defined, `z` if all are z, else `x`. A partial top digit pads with
    /// 0, so a 5-bit all-z vector prints `xz`, as in 4vl.
    fn to_digits(&self, g: usize) -> String {
        let full = (1u64 << g) - 1;
        (0..self.bits.div_ceil(g))
            .rev()
            .map(|d| {
                let a = field(self.a(), d * g, g);
                let b = field(self.b(), d * g, g);
                if a ^ b == 0 {
                    char::from_digit(a as u32, 16).unwrap()
                } else if a & !b == full {
                    'z'
                } else {
                    'x'
                }
            })
            .collect()
    }

    pub fn to_oct(&self) -> String {
        self.to_digits(3)
    }

    pub fn to_hex(&self) -> String {
        self.to_digits(4)
    }

    /// The value if it is fully defined and fits (0 for an empty vector).
    pub fn to_u64(&self) -> Option<u64> {
        (self.bits <= 64 && self.is_fully_defined()).then(|| self.a().first().copied().unwrap_or(0))
    }

    /// The two's-complement value if it is fully defined, not empty and fits.
    pub fn to_i64(&self) -> Option<i64> {
        let v = self.to_u64()?;
        match self.bits {
            0 => None,
            64 => Some(v as i64),
            n => Some(((v << (64 - n)) as i64) >> (64 - n)),
        }
    }
}
